/* Crystal Cleaning Operations Hub — all controls communicate with the FastAPI backend. */
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const aud=v=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v)||0);
const human=s=>String(s||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
let cloudHosted=false;let me=null,tab='overview',cache={},lastRows=[],cameraStream=null,cameraLoop=null;
const tabs=[['BUSINESS','overview','◈','Overview'],['OPERATIONS','clients','♧','Clients'],['','sites','▣','Cleaning Sites'],['','employees','♙','Employees'],['','timesheets','◷','Timesheets'],['','equipment','▤','Equipment Register'],['FINANCE','payroll','▥','Payroll & Payslips'],['','invoices','▧','Invoices'],['','expenses','◇','Expenses'],['SUPPLIES','inventory','▦','Stock Inventory'],['','requests','⇄','Stock Requests'],['SYSTEM','settings','⚙','Settings'],['','users','♧','User Accounts'],['','audit','☷','Audit Log']];
const meta={
 clients:{title:'Clients',subtitle:'Manage customer contacts, billing details and account status.',key:'name',fields:[['name','Client / business name','text',true],['code','Unique client code','text',true],['contact','Contact person'],['email','Email','email'],['phone','Phone'],['address','Billing address','textarea'],['abn','Australian Business Number'],['payment_terms','Payment terms (days)','number'],['notes','Notes','textarea'],['active','Active','checkbox']],columns:['code','name','contact','email','phone','active']},
 sites:{title:'Cleaning Sites',subtitle:'Contracts, schedules, staffing and site-level operations.',key:'name',fields:[['name','Site name','text',true],['code','Unique site code','text',true],['client_id','Client','clients',true],['address','Site address','textarea'],['contact','Contact person'],['phone','Phone'],['schedule','Cleaning schedule','textarea'],['contract_start','Contract start','date'],['contract_end','Contract end','date'],['monthly_value','Monthly contract value (AUD)','number'],['gst_rate','GST percentage','number'],['invoice_day','Recurring invoice day (1–28)','number'],['auto_invoice','Automatic monthly invoice','checkbox'],['notes','Notes','textarea'],['active','Active','checkbox']],columns:['code','name','client_id','address','monthly_value','active']},
 employees:{title:'Employees',subtitle:'Award classifications, employment records and site assignments.',key:'name',fields:[['employee_code','Employee ID','text',true],['name','Employee name','text',true],['email','Email','email'],['phone','Phone'],['address','Address','textarea'],['job_title','Job title'],['employment_type','Employment type','enum:full_time|part_time|casual'],['award_level','Cleaning Award level','enum:1|2|3'],['base_rate','Base award hourly rate (AUD)','number'],['start_date','Start date','date'],['supervisor','Supervisor'],['emergency_contact','Emergency contact'],['super_fund','Super fund name'],['super_member','Super member reference'],['tax_free_threshold','Claims tax-free threshold','checkbox'],['payg_manual','Special PAYG circumstances — manual review','checkbox'],['notes','Notes','textarea'],['active','Active','checkbox']],columns:['employee_code','name','employment_type','award_level','base_rate','active']},
 equipment:{title:'Equipment Register',subtitle:'Track machines, tools and assets with printable barcodes and mobile QR lookups.',key:'name',fields:[['asset_code','Unique equipment / barcode ID'],['name','Equipment name','text',true],['category','Category'],['brand','Brand'],['model','Model'],['serial_number','Serial number'],['site_id','Allocated site','sites'],['assigned_employee_id','Assigned employee','employees'],['purchase_date','Purchase date','date'],['purchase_cost','Purchase cost (AUD)','number'],['condition','Condition','enum:New|Good|Fair|Needs repair|Damaged'],['status','Status','enum:In service|Under maintenance|Out of service|Retired'],['last_service','Last serviced','date'],['next_service','Next service due','date'],['warranty_end','Warranty end','date'],['notes','Notes','textarea'],['active','Active','checkbox']],columns:['asset_code','name','category','site_id','condition','status','next_service','active']},
 products:{title:'Product Catalogue',subtitle:'Purchasing costs, suppliers and site-level stock.',key:'name',fields:[['sku','SKU','text',true],['name','Product','text',true],['category','Category'],['brand','Brand'],['unit','Unit'],['supplier','Supplier'],['cost','Purchase cost (AUD)','number'],['sell_price','Selling price (AUD)','number'],['gst_rate','GST %','number'],['reorder_level','Reorder threshold','number'],['notes','Notes','textarea'],['active','Active','checkbox']],columns:['sku','name','category','unit','cost','sell_price','reorder_level','active']},
 expenses:{title:'Expenses',subtitle:'Record site-specific and company-wide operating costs.',key:'description',fields:[['date','Expense date','date',true],['site_id','Site (optional)','sites'],['category','Category','enum:Labour|Chemicals|Equipment|Transport|Maintenance|Utilities|Office|Other'],['description','Description','text',true],['amount','Total cost (AUD)','number',true],['supplier','Supplier']],columns:['date','description','category','site_id','amount','supplier']}
};
const navNotes={overview:['Business Overview','Real-time visibility across your cleaning operation.'],payroll:['Payroll & Payslips','Create pay runs from approved hours, review PAYG, export payslips.'],invoices:['Invoices & Billing','Service and stock invoices, GST and payment tracking.'],inventory:['Stock Inventory','Track warehouse and site balances without negative stock.'],requests:['Stock Requests','Submit, reserve, dispatch and invoice site supplies.'],settings:['Business Settings','Company identity, billing information and mobile QR access.'],users:['Access Management','Create administrator, manager, supervisor and worker accounts.'],audit:['Activity Audit Log','Review sensitive changes and operational actions.'],timesheets:['Timesheets','Submit shifts and approve worked hours before payroll.']};
function toast(msg,error=false){const r=$('toast-root');r.innerHTML=`<div class="toast ${error?'error':''}">${esc(msg)}</div>`;setTimeout(()=>{r.innerHTML=''},4400)}
async function api(path,method='GET',data){let opt={method,credentials:'same-origin',headers:{}};if(data!==undefined){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(data)}let response;try{response=await fetch(path,opt)}catch(e){throw Error('Cannot reach the server. Check your internet connection or hosting service status.')}let json=await response.json().catch(()=>({}));if(!response.ok){if(response.status===401&&me){me=null;showAuth(false)}throw Error(typeof json.detail==='string'?json.detail:`Request failed (${response.status})`)}return json}
function setHeader(title,kicker,description){$('page-title').textContent=title;$('page-kicker').textContent=kicker;$('page-description').textContent=description;$('breadcrumbs').innerHTML=`Dashboard <span>/ ${esc(title)}</span>`}
function actions(html){$('heading-actions').innerHTML=html||''}
function markNav(){document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.tab===tab))}
function showAuth(setup, requiresSetupKey=false){$('auth').hidden=false;$('shell').hidden=true;$('auth-title').textContent=setup?'Create administrator':'Welcome back';$('auth-description').textContent=setup?'First-time setup. Create the primary administrator account.':'Sign in to manage your cleaning business.';$('setup-fields').hidden=!setup;$('setup-token-field').hidden=!(setup&&requiresSetupKey);$('auth-submit').textContent=setup?'Create account':'Sign in';$('auth').dataset.setup=setup?'yes':'no';$('auth-error').textContent=''}
async function startup(){try{const boot=await api('/api/bootstrap');cloudHosted=!!boot.hosted_mode;if(boot.needs_setup){showAuth(true,boot.requires_setup_key);return}me=await api('/api/me');signedIn()}catch(e){showAuth(false)}}
$('auth-form').addEventListener('submit',async e=>{e.preventDefault();$('auth-error').textContent='';try{const email=$('auth-email').value,password=$('auth-password').value;if($('auth').dataset.setup==='yes'){await api('/api/setup','POST',{email,password,name:$('setup-name').value,company_name:$('setup-company').value,setup_token:$('setup-token').value})}await api('/api/login','POST',{email,password});me=await api('/api/me');signedIn();}catch(err){$('auth-error').textContent=err.message}});
async function logout(){await api('/api/logout','POST').catch(()=>{});me=null;cache={};showAuth(false)}
function signedIn(){ $('auth').hidden=true;$('shell').hidden=false;$('user-name').textContent=me.name;$('user-role').textContent=human(me.role);$('header-chip').textContent=human(me.role);$('avatar').textContent=me.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();$('today').textContent=new Date().toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short',year:'numeric'});let group='';$('nav').innerHTML=tabs.filter(([g,k])=>me.role==='admin'||me.role==='manager'||!['overview','clients','employees','payroll','invoices','expenses','settings','users','audit'].includes(k)).map(([g,k,icon,title])=>{let header=g&&g!==group?`<div class="nav-group">${g}</div>`:'';if(g)group=g;return header+`<button class="nav-item" data-tab="${k}" onclick="navigate('${k}')"><span class="nav-icon">${icon}</span>${esc(title)}</button>`}).join('');navigate(me.role==='admin'||me.role==='manager'?'overview':'sites')}
function navigate(key){tab=key;$('sidebar').classList.remove('open');markNav();$('app-content').innerHTML='<div class="panel empty">Loading records...</div>';actions('');const selected=meta[key]||navNotes[key]||[human(key),''];setHeader(selected.title||selected[0],key==='overview'?'DASHBOARD':key.toUpperCase(),selected.subtitle||selected[1]);const loaders={overview:overview,clients:()=>register('clients'),sites:()=>register('sites'),employees:()=>register('employees'),equipment:equipment,timesheets:timesheetPage,payroll:payrollPage,invoices:invoicePage,expenses:()=>register('expenses'),inventory:inventoryPage,requests:requestPage,settings:settingsPage,users:usersPage,audit:auditPage};Promise.resolve().then(()=>loaders[key]()).catch(e=>{$('app-content').innerHTML=`<div class="panel empty">${esc(e.message)}</div>`;toast(e.message,true)})}
$('mobile-toggle').onclick=()=>$('sidebar').classList.toggle('open');
async function base(name,refresh=false){if(!refresh&&cache[name])return cache[name];cache[name]=await api('/api/register/'+name);return cache[name]}
function lookup(name,id){if(id===null||id===undefined||id==='')return name==='sites'?'Warehouse':'—';let rows=cache[name]||[];let row=rows.find(r=>String(r.id)===String(id));return row?.name||('#'+id)}
async function preload(){await Promise.all(['clients','sites','employees','products'].map(k=>base(k,true).catch(()=>[])))}
function fmt(k,v){if(v===null||v==='')return '<span class="muted">—</span>';if(k==='client_id')return esc(lookup('clients',v));if(k==='site_id'||k==='from_site_id'||k==='to_site_id')return esc(lookup('sites',v));if(k==='employee_id'||k==='assigned_employee_id')return esc(lookup('employees',v));if(k==='product_id')return esc(lookup('products',v));if(['monthly_value','base_rate','amount','cost','sell_price','purchase_cost','total','gross','net','payg','deduction','super_amount','paid'].includes(k))return aud(v);if(k==='active')return status(v?'active':'inactive');if(k==='status'||k==='condition')return status(v);if(typeof v==='boolean')return v?'Yes':'No';return esc(v)}
function status(v){let s=String(v).toLowerCase().replace(/ /g,'_');return `<span class="status ${esc(s)}">${esc(human(v))}</span>`}
function panel(title,body,subtitle=''){return `<div class="panel"><div class="panel-header"><div><h2>${esc(title)}</h2>${subtitle?`<p class="panel-subtitle">${esc(subtitle)}</p>`:''}</div></div>${body}</div>`}
function empty(text='No records yet',hint='Use the New button to create your first record.'){return `<div class="empty"><strong>${esc(text)}</strong>${esc(hint)}</div>`}
function button(text,fn,kind='secondary',cls=''){return `<button class="${kind} ${cls}" onclick="${fn}">${text}</button>`}
function searchTable(id){const val=$('search-data')?.value?.toLowerCase()||'';document.querySelectorAll('#'+id+' tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(val))}
function table(columns,rows,actionFn,id='records-table'){
 if(!rows.length)return empty();let heads=columns.map(c=>`<th>${esc(human(c))}</th>`).join('');if(actionFn)heads+='<th>Actions</th>';
 return `<div class="table-wrap"><table id="${id}"><thead><tr>${heads}</tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(c=>`<td>${fmt(c,r[c])}</td>`).join('')}${actionFn?`<td><div class="table-actions">${actionFn(r)}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function toolbar(links=''){return `<div class="toolbar"><input class="search" id="search-data" placeholder="Search records..." oninput="searchTable('records-table')">${links}</div>`}
function download(name){window.open('/api/export/'+name+'.csv','_blank')}
function modal(title,body,onSave=null,saveLabel='Save changes'){
 $('modal-root').innerHTML=`<div class="modal-overlay" id="modal-shade"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" id="modal-x">×</button></div><div class="modal-body" id="modal-body">${body}</div><div class="modal-footer"><div class="modal-error" id="modal-error" role="alert" hidden></div><button class="button" id="modal-cancel">Cancel</button>${onSave?`<button class="primary" id="modal-save">${esc(saveLabel)}</button>`:''}</div></div></div>`;
 $('modal-x').onclick=closeModal;$('modal-cancel').onclick=closeModal;$('modal-shade').onclick=e=>{if(e.target===$('modal-shade'))closeModal()};
 if(onSave)$('modal-save').onclick=async()=>{let btn=$('modal-save');btn.disabled=true;$('modal-error').hidden=true;try{await onSave();closeModal();toast('Saved successfully');navigate(tab)}catch(e){$('modal-error').textContent=e.message;$('modal-error').hidden=false;btn.disabled=false}}
}
function closeModal(){$('modal-root').innerHTML=''}
function opt(name,selected,allowBlank=true){let options=cache[name]||[];return (allowBlank?'<option value="">Warehouse / None</option>':'')+options.map(x=>`<option value="${x.id}" ${String(selected??'')===String(x.id)?'selected':''}>${esc(x.name||x.sku)}</option>`).join('')}
function fField(def,val){const [key,label,type='text',required=false]=def;let content='',name=esc(key),value=val??'';
 if(type==='checkbox')return `<div class="form-field"><label class="check-field"><input type="checkbox" name="${name}" ${value?'checked':''}>${esc(label)}</label></div>`;
 if(type==='textarea')content=`<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea>`;
 else if(['clients','sites','employees','products'].includes(type))content=`<select name="${name}" ${required?'required':''}>${opt(type,value,!required)}</select>`;
 else if(type.startsWith('enum:'))content=`<select name="${name}">${type.slice(5).split('|').map(x=>`<option value="${esc(x)}" ${String(value)===x?'selected':''}>${esc(human(x))}</option>`).join('')}</select>`;
 else content=`<input name="${name}" type="${type==='number'?'number':type==='date'?'date':type==='email'?'email':'text'}" ${type==='number'?'step="any"':''} value="${esc(value)}" ${required?'required':''}>`;
 return `<div class="form-field ${type==='textarea'?'full':''}"><label>${esc(label)} ${required?'<b>*</b>':''}${content}</label></div>`}
function formValues(fields){let values={};let root=$('modal-body');for(let [k,_,type='text',required] of fields){let el=root.querySelector(`[name="${k}"]`);if(!el)continue;let value=type==='checkbox'?el.checked:el.value;if(required&&(value===''||value===null))throw Error(`${human(k)} is required`);if(value===''&&['clients','sites','employees','products'].includes(type))value=null;if(type==='number'&&value!=='')value=Number(value);if(type==='number'&&value==='')value=0;if(k==='site_id'||k==='assigned_employee_id')value=value||null;values[k]=value}return values}
async function formModal(name,row=null){await preload();let m=meta[name],fields=m.fields;let defaults={payment_terms:14,gst_rate:10,invoice_day:1,auto_invoice:true,employment_type:'casual',award_level:1,base_rate:27.08,tax_free_threshold:true,active:true,unit:'each',reorder_level:5,date:new Date().toISOString().slice(0,10),condition:'Good',status:'In service'};
 modal(row?'Edit '+m.title:'New '+m.title,`<div class="form-grid">${fields.map(f=>fField(f,row?row[f[0]]:defaults[f[0]])).join('')}</div>`,async()=>{
 let values=formValues(fields);if(name==='equipment'&&!values.asset_code)delete values.asset_code;
 const endpoint='/api/register/'+name+(row?'/'+row.id:'');await api(endpoint,row?'PUT':'POST',values);cache[name]=null},row?'Update record':'Create record')}
async function archive(name,id){modal('Archive record',`<p>This record will be archived instead of erased, preserving associated business history. You can restore it later.</p>`,async()=>{await api('/api/register/'+name+'/'+id,'DELETE');cache[name]=null},'Archive record')}
async function restore(name,id){await api('/api/register/'+name+'/'+id+'/restore','POST');cache[name]=null;toast('Record restored');navigate(tab)}
async function register(name){await preload();const m=meta[name],rows=await base(name,true);actions(['admin','manager'].includes(me.role)?button('+ New '+(name==='expenses'?'Expense':name.slice(0,-1)) ,`formModal('${name}')`,'primary')+button('Export CSV',`download('${name}')`):'');
 $('app-content').innerHTML=panel(m.title,toolbar(`<span class="tag">${rows.length} records • Archived entries retained</span>`)+table(m.columns,rows,r=>`${['admin','manager'].includes(me.role)?button('Edit',`formModal('${name}',lastRows.find(x=>x.id===${r.id}))`,'secondary','small'):''} ${['admin','manager'].includes(me.role)?(r.active===false?button('Restore',`restore('${name}',${r.id})`,'secondary','small'):button(name==='expenses'?'Delete':'Archive',`archive('${name}',${r.id})`,'secondary','small delete')):''}${name==='sites'?button('Overview',`siteDetails(${r.id})`,'secondary','small'):''}${name==='employees'&&['admin','manager'].includes(me.role)?button('Sites',`employeeSites(${r.id})`,'secondary','small'):''}`));lastRows=rows;
}
async function siteDetails(id){await preload();let r=await api('/api/site/'+id+'/overview');let employees=r.employee_ids.map(i=>lookup('employees',i)).join(', ')||'None assigned';modal(r.site.name+' — Site overview',`<div class="split"><div class="mini-stat">Total invoiced<b>${aud(r.invoiced)}</b></div><div class="mini-stat">Expenses recorded<b>${aud(r.expenses)}</b></div><div class="mini-stat">Hours recorded<b>${r.timesheet_hours}</b></div><div class="mini-stat">Equipment allocated<b>${r.equipment.length}</b></div></div><div class="divider"></div><h3>Assigned employees</h3><p>${esc(employees)}</p><h3>Equipment</h3><p>${esc(r.equipment.map(e=>e.asset_code+' - '+e.name).join(', ')||'No equipment')}</p>`,null)}
async function employeeSites(id){await preload();let assignments=await api('/api/assignments'),mine=assignments.filter(a=>a.employee_id===id);modal('Employee site assignments',`<div class="form-stack"><p>Current sites: ${esc(mine.map(a=>lookup('sites',a.site_id)).join(', ')||'None')}</p><div class="form-field"><label>Assign additional site<select id="assign-site">${opt('sites','',false)}</select></label></div><button class="primary" onclick="saveAssign(${id})">Assign worker</button><div class="divider"></div>${mine.map(a=>`<div class="quick-link">${esc(lookup('sites',a.site_id))}<button onclick="removeAssign(${a.id},${id})">Remove</button></div>`).join('')}</div>`,null)}
async function saveAssign(id){try{await api('/api/assignments','POST',{employee_id:id,site_id:Number($('assign-site').value)});toast('Worker assigned');employeeSites(id)}catch(e){toast(e.message,true)}}
async function removeAssign(id,employee_id){try{await api('/api/assignments/'+id,'DELETE');toast('Assignment removed');employeeSites(employee_id)}catch(e){toast(e.message,true)}}
async function overview(){await preload();let x=await api('/api/dashboard/summary'),inv=await api('/api/invoices'),requests=await api('/api/stock/requests');const kpis=[['Active clients',x.clients,'♧'],['Cleaning sites',x.sites,'▣'],['Employees',x.employees,'♙'],['Equipment assets',x.equipment,'▤'],['Invoiced this month',aud(x.invoiced_month),'＄'],['Payments this month',aud(x.revenue_month),'↗'],['Outstanding invoices',aud(x.outstanding),'◷'],['Payroll this month',aud(x.payroll_month),'▥'],['Expenses this month',aud(x.expenses_month),'◇'],['Stock inventory value',aud(x.inventory_value),'▦'],['Low stock entries',x.low_stock,'!'],['Pending requests',x.stock_requests_pending,'⇄']];
 actions(button('+ New equipment',"formModal('equipment')",'primary'));
 let months=[];for(let i=5;i>=0;i--){let d=new Date(),v=new Date(d.getFullYear(),d.getMonth()-i,1);let key=v.toISOString().slice(0,7);months.push({key,short:v.toLocaleDateString('en-AU',{month:'short'}),sum:inv.filter(x=>x.issue_date.startsWith(key)).reduce((a,b)=>a+b.total,0)})}
 let max=Math.max(1,...months.map(x=>x.sum));$('app-content').innerHTML=`<div class="kpi-grid">${kpis.map(([label,value,ic])=>`<div class="card kpi"><div class="kpi-head"><span class="kpi-label">${label}</span><span class="kpi-icon">${ic}</span></div><div class="kpi-number">${value}</div><div class="kpi-foot">Live company data</div></div>`).join('')}</div><div class="grid-two"><div class="panel"><div class="panel-header"><div><h2>Invoice revenue trend</h2><p class="panel-subtitle">Service and stock invoice values • Last six months</p></div><span class="tag">AUD</span></div><div class="chart">${months.map(m=>`<div class="chart-col" title="${esc(m.key)}: ${aud(m.sum)}"><div class="chart-bar" style="height:${Math.max(3,m.sum/max*170)}px"></div><div class="chart-name">${m.short}</div></div>`).join('')}</div></div><div class="panel"><div class="panel-header"><div><h2>Quick operations</h2><p class="panel-subtitle">Frequently used workflows</p></div></div>${[['Register a new piece of equipment','equipment'],['Allocate employees to cleaning sites','employees'],['Approve timesheets','timesheets'],['Process stock requests','requests'],['Create Australian payslips','payroll'],['Generate client invoices','invoices']].map(([t,k])=>`<div class="quick-link">${esc(t)}<button onclick="navigate('${k}')">Open →</button></div>`).join('')}</div></div><div class="panel"><div class="panel-header"><h2>Recent invoices</h2></div>${table(['number','kind','issue_date','total','paid','status'],inv.slice(0,6),null,'recent-invoices')}</div>`;
}
async function equipment(){await register('equipment');actions(['admin','manager'].includes(me.role)?button('+ Register equipment',"formModal('equipment')",'primary')+button('Export CSV',"download('equipment')"):'');let rows=lastRows;
 $('app-content').innerHTML=`${panel('Scan a barcode or asset ID',`<div class="toolbar"><input class="search" id="asset-search" placeholder="e.g. EQ-000123 or scan barcode" onkeydown="if(event.key==='Enter')findAsset()"><div class="heading-actions">${button('Find equipment','findAsset()','primary')}${button('Use phone camera','scanCamera()')}</div></div><div class="info">Each equipment label prints a Code 128 barcode and QR code. Barcodes open its record when scanned while signed in. QR codes open a limited equipment summary on any phone with network access.</div>`)}${panel('Company equipment',toolbar(`<span class="tag">${rows.length} registered assets</span>`)+table(meta.equipment.columns,rows,r=>`${['admin','manager'].includes(me.role)?button('Edit',`formModal('equipment',lastRows.find(x=>x.id===${r.id}))`):''}${me.role!=='worker'?button('QR / Label',`assetLabel(${r.id})`):''}${button('History',`assetHistory(${r.id})`)}${['admin','manager'].includes(me.role)?(r.active===false?button('Restore',`restore('equipment',${r.id})`):button('Archive',`archive('equipment',${r.id})`)):''}`))}`
}
async function findAsset(){let code=$('asset-search').value.trim();if(!code)return;try{let eq=await api('/api/equipment/by-code/'+encodeURIComponent(code));assetLabel(eq.id)}catch(e){toast(e.message,true)}}
async function assetLabel(id){await preload();let eq=(cache.equipment||lastRows).find(x=>x.id===id);if(!eq){let r=await base('equipment',true);eq=r.find(x=>x.id===id)}if(!eq)return toast('Record not found',true);
 let qr='/api/equipment/'+id+'/qr.png';modal('Equipment QR / barcode label',`<div class="split"><div><div class="asset-id">${esc(eq.asset_code)}</div><h2 style="margin:10px 0">${esc(eq.name)}</h2><p>Currently allocated to: <b>${esc(lookup('sites',eq.site_id))}</b></p><p class="muted">${esc(eq.brand)} ${esc(eq.model)}</p><div class="info">Download the asset label as a PDF, print it on waterproof sticker stock, and attach it to the equipment. The QR URL is set using your Public Base URL in Settings.</div><a class="primary" style="display:inline-block" href="/api/equipment/${id}/label.pdf" target="_blank">Download printable PDF label</a></div><div><img class="qr-preview" src="${qr}" alt="Equipment QR code"><p class="text-note" style="text-align:center">Scan to view equipment details</p></div></div>`,null)}
async function assetHistory(id){let items=await api('/api/equipment/'+id+'/events');modal('Equipment history',`<div class="toolbar"><button class="primary" onclick="newAssetEvent(${id})">+ Log maintenance / inspection</button></div>${table(['date','event_type','description','cost','recorded_by'],items,null,'history-table')}`,null)}
function newAssetEvent(id){modal('Log equipment event',`<div class="form-grid">${[['event_type','Event','enum:Maintenance|Inspection|Repair|Damage|Note|Service'],['date','Date','date'],['cost','Cost (AUD)','number'],['description','Details','textarea']].map(f=>fField(f,f[0]==='date'?new Date().toISOString().slice(0,10):undefined)).join('')}</div>`,async()=>{let values=formValues([['event_type','','enum:Maintenance|Inspection|Repair|Damage|Note|Service'],['date','','date'],['cost','','number'],['description','','textarea']]);await api('/api/equipment/'+id+'/events','POST',values)},'Log event')}
async function scanCamera(){if(!navigator.mediaDevices?.getUserMedia||!('BarcodeDetector' in window))return toast('Camera barcode scanning is unsupported here. Use the asset ID box or an external scanner.',true);try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});$('scan-camera').hidden=false;$('camera-video').srcObject=cameraStream;const detector=new BarcodeDetector({formats:['code_128','qr_code']});cameraLoop=setInterval(async()=>{try{let codes=await detector.detect($('camera-video'));if(!codes.length)return;let code=codes[0].rawValue;stopCamera();if(code.startsWith('http')){window.open(code,'_blank');return}$('asset-search').value=code;findAsset()}catch(e){}},600)}catch(e){toast('Could not start camera: '+e.message,true)}}
function stopCamera(){if(cameraLoop)clearInterval(cameraLoop);cameraLoop=null;if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;$('scan-camera').hidden=true}

async function timesheetPage(){await preload();let items=await api('/api/timesheets/all');actions(button('+ Submit timesheet','newTimesheet()','primary')+(['admin','manager'].includes(me.role)?button('Export CSV',"download('timesheets')") :''));
 $('app-content').innerHTML=`${panel('Timesheet approvals',toolbar('<span class="tag">Only approved hours enter payroll</span>')+table(['work_date','employee_id','site_id','hours','category','hourly_rate','allowance','status'],items,r=>`${r.status==='pending'&&(me.role==='admin'||me.role==='manager'||me.role==='supervisor')?button('Approve',`timesheetStatus(${r.id},'approved')`)+button('Reject',`timesheetStatus(${r.id},'rejected')`):''}${!r.payrun_id?button('Delete',`removeTimesheet(${r.id})`):'<span class="tag">In payroll</span>'}`))}`;
}
async function newTimesheet(){await preload();let defs=[['employee_id','Employee','employees',true],['site_id','Cleaning site','sites',true],['work_date','Work date','date',true],['start_time','Start time','time'],['end_time','End time','time'],['break_minutes','Unpaid break (minutes)','number'],['category','Pay category','enum:ordinary|early|night|saturday|sunday|public_holiday|overtime_1|overtime_2'],['allowance','Taxable allowance (AUD)','number'],['notes','Notes','textarea']];
 let body=`<div class="info">The recorded hourly rate is snapshotted using the employee’s adult Cleaning Services Award level, employment type and selected shift category. Check actual award rules and entitlements before approval.</div><div class="form-grid">${defs.map(f=>fField(f,({work_date:new Date().toISOString().slice(0,10),start_time:'09:00',end_time:'17:00',break_minutes:30,allowance:0,employee_id:me.employee_id})[f[0]])).join('')}</div>`;
 modal('Submit employee timesheet',body,async()=>{let data=formValues(defs);await api('/api/timesheets/new','POST',data)},'Submit timesheet')}
