async function payrollPage(){await preload();let [runs,ready]=await Promise.all([api('/api/payruns'),api('/api/payroll/ready')]);actions(button('+ Generate pay run','newPayroll()','primary')+button('Export payroll CSV',"download('payroll')"));
 const guidance=ready.count?`<b>${ready.count} approved, unprocessed timesheets</b> covering ${ready.hours} hours for ${ready.employees} workers (from ${esc(ready.earliest_date)} to ${esc(ready.latest_date)}). Choose a period containing the shifts you want to pay.`:'<b>No approved timesheets ready for payroll.</b> Open Timesheets, add shifts for assigned employees and approve them before generating a pay run.';
 $('app-content').innerHTML=`<div class="info warning"><b>Australian payroll review:</b> PAYG calculations cover selected resident 2026 schedules only. Award classifications, allowances, overtime, leave, super and tax declarations must be checked. STP and super payments are not integrated; do not use as an unreviewed live payroll system.</div><div class="info">${guidance} <button class="secondary small" onclick="navigate('timesheets')">Open Timesheets</button></div>${runs.length?runs.map(r=>panel(`Pay run #${r.id} — ${r.period_start} to ${r.period_end}`,`<div class="toolbar"><div class="pill-row">${status(r.status)}<span class="tag">Pay date ${esc(r.pay_date)}</span><span class="tag">${esc(human(r.frequency))}</span></div><div class="heading-actions">${r.status==='draft'?button('Cancel run',`payrunTransition(${r.id},'cancelled')`)+button('Approve payroll',`payrunTransition(${r.id},'approved')`,'primary'):''}${r.status==='approved'?button('Mark paid',`payrunPaid(${r.id})`,'primary'):''}</div></div>${table(['employee_id','gross','payg','deduction','super_amount','net'],r.items,i=>`${i.payg_needs_review?'<span class="status pending">PAYG review</span>':''}${r.status==='draft'?button('Adjust',`adjustPay(${i.id},${i.payg},${i.deduction},${i.super_amount})`):['approved','paid'].includes(r.status)?button('PDF payslip',`downloadPayslip(${i.id})`):'<span class="muted">Cancelled</span>'}`,'payrun-'+r.id)}`)).join(''):panel('No pay runs',empty('Payroll is empty','Create approved timesheets, then generate your first payroll run.'))}`;
}
function payrollLocalDate(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
async function newPayroll(){
 try{
  const ready=await api('/api/payroll/ready');
  if(!ready.count){modal('No timesheets ready for payroll','<div class="info warning">There are no approved timesheets waiting to be paid. Open Timesheets, submit shifts and select Approve. Then return to Payroll and generate a pay run.</div><button class="primary" onclick="closeModal();navigate(\'timesheets\')">Open Timesheets</button>');return}
  let today=new Date(),end=ready.latest_date?new Date(ready.latest_date+'T12:00:00'):new Date(today),start=new Date(end);
  start.setDate(end.getDate()-13);
  let defaults={period_start:payrollLocalDate(start),period_end:payrollLocalDate(end),pay_date:payrollLocalDate(today),frequency:'fortnightly'};
  let defs=[['period_start','Start date','date',true],['period_end','End date','date',true],['pay_date','Pay date','date',true],['frequency','Pay frequency','enum:weekly|fortnightly|monthly']];
  modal('Generate payroll from approved timesheets',`<div class="info"><b>${ready.count} approved timesheets</b> across ${ready.employees} employees, dated ${esc(ready.earliest_date)} to ${esc(ready.latest_date)}. Default dates include the latest shift. Adjust to match your actual pay period (7 days weekly, 14 days fortnightly, or 28–31 days monthly).</div><div class="form-grid">${defs.map(f=>fField(f,defaults[f[0]])).join('')}</div>`,async()=>{const fields=formValues(defs);let a=new Date(fields.period_start+'T12:00:00'),z=new Date(fields.period_end+'T12:00:00');let days=Math.round((z-a)/86400000)+1;
   if(!Number.isFinite(days)||days<1)throw Error('End date must be on or after the start date');
   if((fields.frequency==='weekly'&&days!==7)||(fields.frequency==='fortnightly'&&days!==14)||(fields.frequency==='monthly'&&(days<28||days>31)))throw Error('Select a '+(fields.frequency==='weekly'?'7-day':fields.frequency==='fortnightly'?'14-day':'28–31-day')+' pay period. Current selection is '+days+' days.');
   await api('/api/payruns','POST',fields);
  },'Generate draft payroll');
 }catch(e){toast(e.message,true)}
}
function adjustPay(id,payg,deduction,superAmount){let fields=[['payg','PAYG withholding (AUD)','number'],['deduction','Other deductions (AUD)','number'],['super_amount','Super guarantee estimate (AUD)','number']];modal('Adjust draft payroll item',`<div class="info warning">Only enter a PAYG override after checking the employee’s actual tax declaration and applicable ATO tables. The system saves an audit trail. Net pay is recalculated immediately.</div><div class="form-grid">${fields.map(f=>fField(f,({payg,deduction,super_amount:superAmount})[f[0]])).join('')}</div>`,async()=>{await api('/api/payitems/'+id,'PATCH',formValues(fields))},'Apply adjustment')}
async function payrunTransition(id,status){modal(human(status)+' pay run',`<p>${status==='approved'?'Approving locks payroll calculations and releases downloadable payslips. Confirm all tax, award and super entitlements have been reviewed.':'Cancelling releases timesheets for a new pay run. This action cannot be reversed.'}</p>`,async()=>{await api('/api/payruns/'+id+'/status','POST',{status})},human(status)+' pay run')}
function payrunPaid(id){modal('Record payroll as paid',`<div class="info warning">Confirm bank transfers and required superannuation payments separately. This button records payment status only; it does not transfer funds or report to the ATO.</div><div class="form-field"><label>Bank payment batch/reference<input id="paid-ref" required placeholder="e.g. PAY-2026-018"></label></div>`,async()=>{let payment_reference=$('paid-ref').value.trim();if(!payment_reference)throw Error('Payment reference is required');await api('/api/payruns/'+id+'/status','POST',{status:'paid',payment_reference})},'Mark as paid')}
function downloadPayslip(id){window.open('/api/payitems/'+id+'/payslip.pdf','_blank')}

async function invoicePage(){await preload();let inv=await api('/api/invoices');actions(button('+ New invoice','newInvoice()','primary')+button('Generate recurring', 'generateRecurring()')+button('Export CSV',"download('invoices')"));
 $('app-content').innerHTML=`${panel('Accounts receivable',toolbar(`<span class="tag">${inv.length} invoices</span>`)+table(['number','kind','client_id','site_id','issue_date','due_date','total','paid','status'],inv,i=>`${button('PDF',`openInvoice(${i.id})`)}${i.total>i.paid?button('Record payment',`invoicePayment(${i.id},${i.total-i.paid})`):''}${i.status==='draft'?button('Mark sent',`markInvoiceSent(${i.id})`):''}${button('Email',`emailInvoice(${i.id})`)}`))}`;
}
function openInvoice(id){window.open('/api/invoices/'+id+'/pdf','_blank')}
function addInvoiceLine(){let wrap=$('invoice-lines');wrap.insertAdjacentHTML('beforeend',`<div class="line-list"><div class="fields"><input placeholder="Service / description" class="line-desc"><input type="number" min="0.01" step="any" class="line-qty" placeholder="Qty" value="1"><input type="number" min="0" step="any" class="line-price" placeholder="Unit AUD"><button class="button" onclick="this.closest('.line-list').remove()">×</button></div><div class="form-field" style="width:120px;margin-top:9px"><label>GST %<input type="number" step="any" class="line-gst" value="10"></label></div></div>`)}
async function newInvoice(){await preload();let fields=[['client_id','Client','clients',true],['site_id','Site','sites'],['issue_date','Invoice date','date'],['due_date','Due date','date'],['notes','Notes','textarea']];modal('Create service invoice',`<div class="form-grid">${fields.map(f=>fField(f,({issue_date:new Date().toISOString().slice(0,10),due_date:new Date(Date.now()+14*864e5).toISOString().slice(0,10)})[f[0]])).join('')}</div><div class="divider"></div><div class="toolbar"><h3>Invoice lines</h3><button class="button" onclick="addInvoiceLine()">+ Add line</button></div><div id="invoice-lines"></div>`,async()=>{let values=formValues(fields);values.lines=Array.from(document.querySelectorAll('#invoice-lines .line-list')).map(x=>({description:x.querySelector('.line-desc').value,quantity:Number(x.querySelector('.line-qty').value),unit_price:Number(x.querySelector('.line-price').value),gst_rate:Number(x.querySelector('.line-gst').value)}));if(!values.lines.length||values.lines.some(x=>!x.description||!x.quantity))throw Error('Invoice lines need descriptions and quantities');await api('/api/invoices','POST',values)},'Create invoice');addInvoiceLine()}
function generateRecurring(){modal('Generate recurring monthly invoices',`<p>Generate draft invoices for active sites whose configured recurring billing day is due in the current month. Existing site-month invoices are not duplicated.</p>`,async()=>{let r=await api('/api/invoices/recurring','POST');toast(`${r.count} invoices generated`)},'Generate invoices')}
function invoicePayment(id,balance){let fields=[['amount',`Amount (maximum ${aud(balance)})`,'number',true],['date','Payment date','date',true],['reference','Bank reference']];modal('Record invoice payment',`<div class="form-grid">${fields.map(f=>fField(f,({amount:Math.round(balance*100)/100,date:new Date().toISOString().slice(0,10)})[f[0]])).join('')}</div>`,async()=>{await api('/api/invoices/'+id+'/payment','POST',formValues(fields))},'Record payment')}
async function markInvoiceSent(id){try{await api('/api/invoices/'+id+'/status','POST',{status:'sent'});toast('Invoice marked as sent');navigate('invoices')}catch(e){toast(e.message,true)}}
function emailInvoice(id){modal('Email invoice as PDF',`<p>This will send the invoice to the email address saved on the client record. SMTP must be configured in the server's <code>.env</code> file.</p>`,async()=>{await api('/api/invoices/'+id+'/email','POST')},'Send invoice')}

async function inventoryPage(){await preload();let prods=await base('products',true),balances=await api('/api/stock/balances'),movements=['admin','manager'].includes(me.role)?await api('/api/stock/movements'):[];let stock=balances.map(b=>({...b,product_id:b.product_id,site_id:b.site_id,available:Math.round((b.quantity-b.reserved)*100)/100}));
 actions(['admin','manager'].includes(me.role)?button('+ Add product',"formModal('products')",'primary')+button('Stock movement','stockMove()')+button('Export products',"download('products')"):'');
 $('app-content').innerHTML=`<div class="kpi-grid">${[['Products',prods.length,'▦'],['Locations with stock',new Set(balances.map(x=>x.site_id??'warehouse')).size,'▣'],['Stock units',Math.round(balances.reduce((n,x)=>n+x.quantity,0)*100)/100,'▤'],['Reserved units',Math.round(balances.reduce((n,x)=>n+x.reserved,0)*100)/100,'◷']].map(([n,v,ic])=>`<div class="card kpi"><span class="kpi-label">${n}</span><span class="kpi-icon" style="float:right">${ic}</span><div class="kpi-number">${v}</div></div>`).join('')}</div>${panel('Product catalogue',toolbar('Manage active products and pricing')+table(meta.products.columns,prods,r=>`${['admin','manager'].includes(me.role)?button('Edit',`formModal('products',lastRows.find(x=>x.id===${r.id}))`)+(r.active?button('Archive',`archive('products',${r.id})`):button('Restore',`restore('products',${r.id})`)):''}`))}${panel('Warehouse & site balances',table(['product_id','site_id','quantity','reserved','available'],stock,null,'stock-balances'))}${panel('Recent inventory movements',table(['date','product_id','kind','from_site_id','to_site_id','quantity','reference'],movements.slice(0,35),null,'stock-movements'))}`;lastRows=prods}
function stockMove(){let fields=[['kind','Movement type','enum:receipt|transfer|return|consume|damage|loss|adjust_add'],['product_id','Stock product','products',true],['quantity','Quantity','number',true],['from_site_id','Source site (blank = warehouse)','sites'],['to_site_id','Destination site (blank = warehouse)','sites'],['reference','Supplier invoice or movement reference']];modal('Post inventory movement',`<div class="info">Receipt adds stock to a location. Transfer/return moves stock between locations. Consume/damage/loss removes from a location. Adjust Add increases a location. Reserved stock cannot be consumed or transferred.</div><div class="form-grid">${fields.map(f=>fField(f)).join('')}</div>`,async()=>{let values=formValues(fields);values.from_site_id=values.from_site_id||null;values.to_site_id=values.to_site_id||null;await api('/api/stock/move','POST',values)},'Post stock movement')}

async function requestPage(){await preload();let reqs=await api('/api/stock/requests');actions(me.role!=='worker'?button('+ Request stock','newRequest()','primary'):'');
 $('app-content').innerHTML=`<div class="info">Requests move through pending → approved → dispatched → delivered. Approval reserves warehouse stock. Dispatch transfers quantities into the requested site. Stock request invoices are separate from cleaning-service invoices.</div>${reqs.length?reqs.map(r=>panel(`Request REQ-${r.id} • ${lookup('sites',r.site_id)}`,`<div class="toolbar"><div class="pill-row">${status(r.status)}<span class="tag">Requested by ${esc(r.requested_by)}</span><span class="tag">${esc(r.created_at.slice(0,10))}</span></div><div class="heading-actions">${r.status==='pending'?(me.role==='admin'||me.role==='manager'?button('Approve',`approveRequest(${r.id})`,'primary')+button('Reject',`rejectRequest(${r.id})`):''):''}${['approved','partially_fulfilled'].includes(r.status)&&['admin','manager'].includes(me.role)?button('Dispatch',`dispatchRequest(${r.id})`,'primary'):''}${r.status==='dispatched'?button('Confirm delivered',`deliverRequest(${r.id})`):''}${['dispatched','delivered'].includes(r.status)&&['admin','manager'].includes(me.role)?button('Create stock invoice',`stockInvoice(${r.id})`):''}</div></div>${table(['product_id','quantity','approved','dispatched'],r.lines,null,'req-lines-'+r.id)}${r.notes?`<p class="text-note">Notes: ${esc(r.notes)}</p>`:''}`)).join(''):panel('No stock requests yet',empty('No requests yet','A site supervisor or administrator can request supplies.'))}`;
}
function addRequestLine(){let wrap=$('request-lines');wrap.insertAdjacentHTML('beforeend',`<div class="line-list"><div class="fields"><select class="req-product">${opt('products','',false)}</select><input type="number" min="0.01" step="any" value="1" class="req-quantity"><span></span><button class="button" onclick="this.closest('.line-list').remove()">×</button></div></div>`)}
async function newRequest(){await preload();let fields=[['site_id','Requesting site','sites',true],['notes','Additional details','textarea']];modal('New site stock request',`<div class="form-grid">${fields.map(f=>fField(f)).join('')}</div><div class="divider"></div><div class="toolbar"><h3>Requested products</h3><button class="button" onclick="addRequestLine()">+ Add product</button></div><div id="request-lines"></div>`,async()=>{let values=formValues(fields);values.lines=Array.from(document.querySelectorAll('#request-lines .line-list')).map(x=>({product_id:Number(x.querySelector('.req-product').value),quantity:Number(x.querySelector('.req-quantity').value)}));if(!values.lines.length)throw Error('Add products');await api('/api/stock/requests','POST',values)},'Submit request');addRequestLine()}
async function approveRequest(id){let rows=await api('/api/stock/requests'),r=rows.find(x=>x.id===id);modal('Approve / reserve warehouse supplies',`<div class="info warning">Every approved quantity is reserved from available warehouse stock. The approval is atomic; no negative available balance is permitted.</div>${r.lines.map(l=>`<div class="form-field"><label>${esc(lookup('products',l.product_id))} (requested: ${l.quantity})<input type="number" min="0" max="${l.quantity}" step="any" data-approval="${l.id}" value="${l.quantity}"></label></div>`).join('')}`,async()=>{let approved={};document.querySelectorAll('[data-approval]').forEach(x=>approved[x.dataset.approval]=Number(x.value));await api('/api/stock/requests/'+id+'/approve','POST',{approved})},'Approve request')}
function rejectRequest(id){modal('Reject stock request','<p>This rejects the request and releases any reserved quantities. Rejected requests remain in history.</p>',async()=>{await api('/api/stock/requests/'+id+'/reject','POST')},'Reject request')}
async function dispatchRequest(id){let all=await api('/api/stock/requests'),r=all.find(x=>x.id===id);modal('Dispatch stock from warehouse',`<p class="muted">Partial dispatches are supported. Enter the quantity to send now.</p>${r.lines.filter(l=>l.approved>l.dispatched).map(l=>`<div class="form-field"><label>${esc(lookup('products',l.product_id))} (remaining ${Math.round((l.approved-l.dispatched)*100)/100})<input type="number" step="any" min="0" max="${l.approved-l.dispatched}" value="${l.approved-l.dispatched}" data-qty="${l.id}"></label></div>`).join('')}`,async()=>{let quantities={};document.querySelectorAll('[data-qty]').forEach(x=>quantities[x.dataset.qty]=Number(x.value));await api('/api/stock/requests/'+id+'/dispatch','POST',{quantities})},'Dispatch quantities')}
function deliverRequest(id){modal('Confirm site delivery','<p>Confirm that all dispatched quantities have been delivered to the cleaning site.</p>',async()=>{await api('/api/stock/requests/'+id+'/deliver','POST')},'Confirm delivered')}
function stockInvoice(id){modal('Create itemised stock invoice','<p>Generate a separate GST invoice for all quantities dispatched against this request. It will appear in the Invoices tab.</p>',async()=>{let r=await api('/api/stock/requests/'+id+'/invoice','POST');toast('Created '+r.number)},'Create stock invoice')}

async function settingsPage(){let settings=await api('/api/settings');actions(button('Save business settings','saveSettings()','primary'));
 const fields=[['company_name','Company name'],['company_abn','Company ABN'],['company_address','Registered / billing address','textarea'],['company_email','Company email','email'],['company_phone','Telephone'],['company_bsb','Bank BSB'],['company_account','Bank account number'],['public_base_url','Public Base URL for mobile QR access'],['logo_url','Public logo URL (reserved for future branding)']];
 $('app-content').innerHTML=panel('Company profile',`<div class="info warning">For QR codes to open on phones, set Public Base URL to your LAN computer address (for example http://192.168.1.10:8000) or your hosted HTTPS domain. <b>localhost</b> only works on the computer running the server. Use HTTPS and a properly secured deployment before exposing this app to the internet.</div><div class="form-grid" id="settings-fields">${fields.map(f=>fField(f,settings[f[0]]||'')).join('')}</div><div class="divider"></div><h3>Backup and recovery</h3><p class="text-note">Download a consistent local SQLite database backup. To restore, stop both services and use <code>python restore_backup.py PATH_TO_BACKUP.sqlite3</code>. For PostgreSQL use pg_dump / pg_restore.</p>${cloudHosted?'<p>Cloud database backups: use Neon Console export / pg_dump (see HOSTING_GUIDE.md). The local SQLite backup button is not available in hosted mode.</p>':'<a class="button" style="display:inline-block;margin-top:10px" href="/api/admin/backup">Download database backup</a>'}<div class="divider"></div><h3>Invoice & payroll defaults</h3><p class="muted" style="font-size:12px;line-height:1.8">Currency: AUD • GST: site / product configurable • Timezone: Australia/Melbourne • Super: 12% on the system's currently selected qualifying earnings estimate • SMTP configuration: set in the .env file • Automated invoice worker: run app.scheduler.</p>`);
}
async function saveSettings(){const fields=['company_name','company_abn','company_address','company_email','company_phone','company_bsb','company_account','public_base_url','logo_url'];let values={};fields.forEach(k=>values[k]=document.querySelector(`#settings-fields [name="${k}"]`).value);try{await api('/api/settings','PUT',values);toast('Business settings saved')}catch(e){toast(e.message,true)}}
async function usersPage(){let u=await api('/api/users');await preload();actions(button('+ Add user','newUser()','primary')); $('app-content').innerHTML=panel('System users',table(['name','email','role','site_id','employee_id','active'],u,r=>button('Edit',`editUser(${r.id})`)));cache.users=u}
function userFields(u){return `<div class="form-grid">${[['name','Full name','text',true],['email','Email address','email',true],['role','Access role','enum:admin|manager|supervisor|worker'],['employee_id','Linked employee (workers)','employees'],['site_id','Assigned site (supervisors)','sites'],['password',u?'New password (optional)':'Password (12+ characters)','text'],['active','Active','checkbox']].map(f=>fField(f,u?u[f[0]]:f[0]==='active'?true:undefined)).join('')}</div><p class="text-note">Use a unique password for every user. Worker and supervisor access is restricted to assigned site data.</p>`}
async function newUser(){await preload();modal('Create system user',userFields(null),async()=>{let d={};document.querySelectorAll('#modal-body [name]').forEach(e=>d[e.name]=e.type==='checkbox'?e.checked:e.value);if(!d.password||d.password.length<12)throw Error('Password must be 12 or more characters');await api('/api/users','POST',d)},'Create user')}
async function editUser(id){await preload();let u=(cache.users||[]).find(x=>x.id===id);modal('Edit user account',userFields(u),async()=>{let d={};document.querySelectorAll('#modal-body [name]').forEach(e=>d[e.name]=e.type==='checkbox'?e.checked:e.value);if(!d.password)delete d.password;await api('/api/users/'+id,'PUT',d)},'Update user')}
async function auditPage(){let logs=await api('/api/audit');actions(button('Refresh','navigate("audit")'));$('app-content').innerHTML=panel('Last 250 logged actions',table(['created_at','user_id','event','details'],logs,null,'audit-records'))}
startup();
